int minCapacity(const vector<int>& w, int days) {
    long long lo = 1, hi = accumulate(w.begin(), w.end(), 0LL);
    while (lo < hi) {
        long long cap = lo + (hi - lo) / 2;
        int used = 1;
        long long load = 0;
        for (int x : w) {
            if (load + x > cap) { used++; load = 0; }
            load += x;
        }
        if (used <= days) hi = cap;
        else lo = cap + 1;
    }
    return lo;
}

int longestUnique(const string& s) {
    unordered_map<char, int> last;
    int best = 0, lo = 0;
    for (int hi = 0; hi < (int)s.size(); hi++) {
        if (last.count(s[hi])) lo = last[s[hi]] + 1;
        last[s[hi]] = hi;
        best = max(best, hi - lo + 1);
    }
    return best;
}

int shortestAtLeast(const vector<int>& a, int target) {
    int best = INT_MAX, sum = 0, lo = 0;
    for (int hi = 0; hi < (int)a.size(); hi++) {
        sum += a[hi];
        while (sum >= target) {
            sum -= a[lo++];
            best = min(best, hi - lo + 1);
        }
    }
    return best == INT_MAX ? 0 : best;
}

int longestKDistinct(const string& s, int k) {
    unordered_map<char, int> cnt;
    int best = 0, lo = 0;
    for (int hi = 0; hi < (int)s.size(); hi++) {
        cnt[s[hi]]++;
        while ((int)cnt.size() > k) {
            cnt[s[lo]]--;
            lo++;
        }
        best = max(best, hi - lo + 1);
    }
