}

int minWindow(const string& s, const string& t) {
    vector<int> need(128, 0), have(128, 0);
    for (char c : t) need[c]++;
    int missing = t.size(), best = INT_MAX, lo = 0;
    for (int hi = 0; hi < (int)s.size(); hi++) {
        if (have[s[hi]]++ < need[s[hi]]) missing--;
        while (missing == 0) {
            best = min(best, hi - lo + 1);
            if (--have[s[lo]] <= need[s[lo]]) missing++;
            lo++;
        }
    }
    return best == INT_MAX ? 0 : best;
}

vector<int> windowMax(const vector<int>& a, int k) {
    deque<int> dq;
    vector<int> out;
    for (int i = 0; i < (int)a.size(); i++) {
        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();
        dq.push_back(i);
        if (dq.front() < i - k) dq.pop_front();
        if (i >= k - 1) out.push_back(a[dq.front()]);
    }
    return out;
}

vector<vector<int>> threeSum(vector<int> a) {
    sort(a.begin(), a.end());
    vector<vector<int>> res;
    int n = a.size();
    for (int i = 0; i + 2 < n; i++) {
        if (a[i] == a[i + 1]) continue;
        int l = i + 1, r = n - 1;
        while (l < r) {
            int s = a[i] + a[l] + a[r];
            if (s < 0) l++;
            else if (s > 0) r--;
            else {
                res.push_back({a[i], a[l], a[r]});
                l++; r--;
                while (l < r && a[l] == a[l - 1]) l++;
            }
        }
    }
    return res;
}

