vector<long long> dijkstra(const vector<vector<pair<int, int>>>& g, int s) {
    vector<long long> dist(g.size(), LLONG_MAX);
    vector<char> done(g.size(), 0);
    priority_queue<P, vector<P>, greater<P>> pq;
    dist[s] = 0;
