Node* cloneGraph(Node* n, unordered_map<Node*, Node*>& seen) {
    if (seen.count(n)) return seen[n];
    Node* copy = new Node{n->val, {}};
    for (Node* m : n->nbrs) copy->nbrs.push_back(cloneGraph(m, seen));
    seen[n] = copy;
    return copy;
}

using P = pair<long long, int>;
vector<long long> shortest(const vector<vector<pair<int, int>>>& g, int s) {
    vector<long long> dist(g.size(), LLONG_MAX);
    priority_queue<P, vector<P>, greater<P>> pq;
    dist[s] = 0;
    pq.push({0, s});
    while (!pq.empty()) {
        const auto& [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;
        for (auto [v, w] : g[u]) {
            if (d + w < dist[v]) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

vector<int> topoOrder(int n, const vector<pair<int, int>>& edges) {
    vector<vector<int>> g(n);
    vector<int> indeg(n, 0), order;
    for (auto [u, v] : edges) { g[u].push_back(v); indeg[v]++; }
    queue<int> q;
    for (int i = 0; i < n; i++) if (indeg[i] == 0) q.push(i);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        order.push_back(u);
        for (int v : g[u]) if (--indeg[v] == 0) q.push(v);
    }
    return order;
}

bool canFinish(int n, const vector<pair<int, int>>& edges) {
    vector<set<int>> g(n);
    vector<int> indeg(n, 0);
    for (auto [u, v] : edges) {
        g[u].insert(v);
        indeg[v]++;
    }
    queue<int> q;
    for (int i = 0; i < n; i++) if (indeg[i] == 0) q.push(i);
    int done = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        done++;
        for (int v : g[u]) if (--indeg[v] == 0) q.push(v);
    }
    return done == n;
}

struct DSU {
    vector<int> p;
    DSU(int n) : p(n) { iota(p.begin(), p.end(), 0); }
    int find(int x) { return p[x] == x ? x : p[x] = find(p[x]); }
    void unite(int a, int b) { p[a] = find(b); }
    bool connected(int a, int b) { return find(a) == find(b); }
};

int components(int n, const vector<pair<int, int>>& edges) {
    vector<int> p(n);
    iota(p.begin(), p.end(), 0);
    function<int(int)> find = [&](int x) {
        return p[x] == x ? x : p[x] = find(p[x]);
    };
    for (auto [a, b] : edges) p[find(a)] = find(b);
    set<int> roots(p.begin(), p.end());
    return roots.size();
}

