int editDistance(const string& a, const string& b) {
    int m = a.size(), n = b.size();
    vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));
    for (int i = 1; i <= m; i++) dp[i][0] = i;
    for (int i = 1; i <= m; i++)
        for (int j = 1; j <= n; j++) {
            if (a[i - 1] == b[j - 1]) dp[i][j] = dp[i - 1][j - 1];
            else dp[i][j] = 1 + min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]});
        }
    return dp[m][n];
}

int countPalindromes(const string& s) {
    int n = s.size(), cnt = 0;
    vector<vector<char>> dp(n, vector<char>(n, 0));
    for (int i = 0; i < n; i++)
        for (int j = i; j < n; j++) {
            dp[i][j] = s[i] == s[j] && (j - i < 2 || dp[i + 1][j - 1]);
            cnt += dp[i][j];
        }
    return cnt;
}

void sink(vector<string>& g, int r, int c) {
    if (g[r][c] != '1' || r < 0 || c < 0 ||
        r >= (int)g.size() || c >= (int)g[0].size()) return;
    g[r][c] = '0';
    sink(g, r + 1, c);
    sink(g, r - 1, c);
    sink(g, r, c + 1);
    sink(g, r, c - 1);
}

