int rob(const vector<int>& a) {
    int n = a.size();
    if (n == 0) return 0;
    vector<int> dp(n);
    dp[0] = a[0];
    dp[1] = max(a[0], a[1]);
    for (int i = 2; i < n; i++)
        dp[i] = max(dp[i - 1], dp[i - 2] + a[i]);
    return dp[n - 1];
}

bool oneEdit(const string& a, const string& b) {
    if (a.size() - b.size() > 1) return false;
    size_t i = 0, j = 0;
    bool used = false;
    while (i < a.size() && j < b.size()) {
        if (a[i] == b[j]) { i++; j++; continue; }
        if (used) return false;
        used = true;
        if (a.size() > b.size()) i++;
        else if (a.size() < b.size()) j++;
        else { i++; j++; }
    }
    return true;
}
